package id.imperial.shop;
import org.bukkit.*;import org.bukkit.entity.Player;import org.bukkit.event.*;import org.bukkit.event.inventory.*;import org.bukkit.inventory.*;import org.bukkit.persistence.PersistentDataType;
public final class ShopListener implements Listener{final ShopService s;ShopListener(ShopService s){this.s=s;}
@EventHandler public void click(InventoryClickEvent e){if(!(e.getWhoClicked() instanceof Player p))return;String t=ChatColor.stripColor(e.getView().getTitle());if(!(t.contains("IMPERIAL SHOP")||t.contains("SHOP »")||t.contains("BELI »")||t.contains("SELL GUI")))return;e.setCancelled(true);if(e.getClickedInventory()!=e.getView().getTopInventory())return;ItemStack i=e.getCurrentItem();if(i==null||!i.hasItemMeta())return;var pc=i.getItemMeta().getPersistentDataContainer();String a=pc.get(s.actionKey,PersistentDataType.STRING),n=pc.get(s.itemKey,PersistentDataType.STRING);if(a==null)return;
if(a.equals("sell")){Material m=Material.matchMaterial(n);double total=s.sellMaterial(p,m);if(total>0){s.economy.depositPlayer(p,total);p.sendMessage("§aBerhasil menjual "+s.pretty(m)+": §f"+s.money(total));s.openSell(p);}return;}if(a.equals("sellhand")){double total=s.sellHand(p);if(total>0){s.economy.depositPlayer(p,total);p.sendMessage("§aBerhasil menjual item tangan: §f"+s.money(total));s.openSell(p);}else p.sendMessage("§cItem di tangan tidak memiliki harga jual.");return;}if(a.equals("sellall")){double total=s.sellContents(p);if(total>0){s.economy.depositPlayer(p,total);p.sendMessage("§aBerhasil menjual inventory: §f"+s.money(total));s.openSell(p);}else p.sendMessage("§cTidak ada item yang dapat dijual.");return;}if(a.equals("category")){s.openCategory(p,n);return;}if(a.equals("back")){s.openShop(p);return;}if(a.equals("close")){p.closeInventory();return;}if(a.equals("buy")){s.openQuantity(p,Material.matchMaterial(n));return;}if(a.startsWith("buy:")){int q=Integer.parseInt(a.substring(4));Material m=Material.matchMaterial(n);if(s.buy(p,m,q))p.sendMessage("§aPembelian berhasil: §f"+q+"x "+s.pretty(m));else p.sendMessage("§cSaldo tidak cukup atau inventory tidak memiliki ruang.");return;}if(a.equals("backcat")){Material m=Material.matchMaterial(n);if(m!=null){for(var en:s.cats.entrySet())if(en.getValue().contains(m)){s.openCategory(p,en.getKey());return;}}}}
@EventHandler public void drag(InventoryDragEvent e){String t=ChatColor.stripColor(e.getView().getTitle());if(t.contains("IMPERIAL SHOP")||t.contains("SHOP »")||t.contains("BELI »"))e.setCancelled(true);}}
